module encoder_top
   (clk_gth,
    clk_logic,
    rst_n,
    en,
    data_in,
    flag,
    data_out);
  input clk_gth;
  input clk_logic;
  input rst_n;
  input en;
  input [31:0]data_in;
  output flag;
  output [31:0]data_out;

  wire c16_dv;
  wire c32_dv;
  wire clk_gth;
  wire clk_logic;
  wire [95:0]core_data;
  wire core_dv;
  wire [7:0]crc_16;
  wire [31:0]crc_32;
  wire [31:0]data_in;
  wire [31:0]data_out;
  wire en;
  wire flag;
  wire [7:0]header;
  wire header_dv;
  wire [63:0]payload;
  wire payload_dv;

  core_tx core_tx_inst
       (.clk_logic(clk_logic),
        .core_data(core_data),
        .en(core_dv),
        .header(header),
        .header_dv(header_dv),
        .payload(payload),
        .payload_dv(payload_dv));
  framer_top framer_top_inst
       (.clk_gth(clk_gth),
        .data_in(data_in),
        .en(en),
        .en_head(c16_dv),
        .en_load(c32_dv),
        .header_in(crc_16),
        .payload_in(crc_32));
  x_gth_logic x_gth_logic_inst
       (.clk_gth(clk_gth),
        .clk_logic(clk_logic),
        .en_head(c16_dv),
        .en_load(c32_dv),
        .header(header),
        .header_dv(header_dv),
        .header_in(crc_16),
        .payload(payload),
        .payload_dv(payload_dv),
        .payload_in(crc_32));
  x_logic_gth x_logic_gth_inst
       (.clk_gth(clk_gth),
        .clk_logic(clk_logic),
        .\count_reg[1]_0 (flag),
        .data_in(core_data),
        .data_out(data_out),
        .en(core_dv));
endmodule

