module framer_top
   (en_head,
    header_in,
    payload_in,
    en_load,
    clk_gth,
    data_in,
    en);
  output en_head;
  output [7:0]header_in;
  output [31:0]payload_in;
  output en_load;
  input clk_gth;
  input [31:0]data_in;
  input en;

  wire clk_gth;
  wire [7:0]crc_16;
  wire [31:0]crc_32;
  wire [31:0]data_in;
  wire en;
  wire en_head;
  wire en_load;
  wire framer_inst_n_0;
  wire framer_inst_n_1;
  wire [7:0]header_in;
  wire [31:0]payload_in;

  crc_16 crc_16_inst
       (.\FSM_onehot_state_reg[1]_0 (framer_inst_n_1),
        .clk_gth(clk_gth),
        .crc_16(crc_16),
        .en_head(en_head),
        .header_in(header_in));
  crc_32 crc_32_inst
       (.\FSM_onehot_state_reg[1]_0 (framer_inst_n_0),
        .clk_gth(clk_gth),
        .crc_32(crc_32),
        .en_load(en_load),
        .payload_in(payload_in));
  framer framer_inst
       (.clk_gth(clk_gth),
        .\count_reg[3]_0 (framer_inst_n_0),
        .\count_reg[3]_1 (framer_inst_n_1),
        .crc_16(crc_16),
        .crc_32(crc_32),
        .data_in(data_in),
        .en(en));
endmodule

